INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/53735e0f01570085514ad3900423782c4965fd11/content/books/zizhi-tongjian/vol-288/year-0948/part-02/sources/library/jiuwudaishi-101-april-dingzhou-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002454；EPUB电子本，纸本及异文待核", "id": "00e8a9b2-6342-5a03-a9f0-100178652976"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/53735e0f01570085514ad3900423782c4965fd11/content/books/zizhi-tongjian/vol-288/year-0948/part-02/sources/library/jiuwudaishi-101-march-close-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002453；EPUB电子本，纸本及异文待核", "id": "1ca67e72-a36a-5c37-b0f3-eb50ae101bf6"}, {"title": "宋史·巻二百七十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/53735e0f01570085514ad3900423782c4965fd11/content/books/zizhi-tongjian/vol-288/year-0948/part-02/sources/library/songshi-274-tian-lingfang-death/source.txt", "note": "《宋史》巻二百七十四，段落 songshi-9c6e46fee832-p059176；EPUB电子本，纸本及异文待核", "id": "e4789a17-0e55-5f1d-b26d-8139c5928b67"}, {"title": "新五代史·卷四十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/53735e0f01570085514ad3900423782c4965fd11/content/books/zizhi-tongjian/vol-288/year-0948/part-02/sources/library/xinwudaishi-049-sun-reoccupies-dingzhou/source.txt", "note": "《新五代史》卷四十九，段落 xin-wudaishi-b08f244b9241-p001924；EPUB电子本，纸本及异文待核", "id": "3ac22073-9451-537d-934a-2a22de1bfdf3"}, {"title": "新五代史·卷四十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/53735e0f01570085514ad3900423782c4965fd11/content/books/zizhi-tongjian/vol-288/year-0948/part-02/sources/library/xinwudaishi-049-sun-transfer/source.txt", "note": "《新五代史》卷四十九，段落 xin-wudaishi-b08f244b9241-p001923；EPUB电子本，纸本及异文待核", "id": "a3d38546-e96c-5d96-b0e9-5a4a79aa8122"}, {"title": "新五代史·卷五十三", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/53735e0f01570085514ad3900423782c4965fd11/content/books/zizhi-tongjian/vol-288/year-0948/part-02/sources/library/xinwudaishi-053-siwan-seizes-changan/source.txt", "note": "《新五代史》卷五十三，段落 xin-wudaishi-b08f244b9241-p002072；EPUB电子本，纸本及异文待核", "id": "7b0d6e91-eb96-59a0-a517-c4f0433f1257"}, {"title": "资治通鉴·后汉纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ba6eb38778a9dc93b1118241befc00658469f072/content/books/zizhi-tongjian/vol-288/year-0948/part-01/sources/library/tongjian-288-948-march/source.txt", "note": "《资治通鉴》后汉纪三，段落 zizhi-tongjian-a63549944a71-p003415；电子底本待考，分段待核", "id": "3e2d1144-929c-5695-baef-ad43337f9477"}, {"title": "旧五代史·卷一百〇九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/81c86a2a7b16e48591c2de043347d16f153f6a6a/content/books/zizhi-tongjian/vol-287/year-0948/part-01/sources/library/jiuwudaishi-109-zhao-siwan-origin/source.txt", "note": "《旧五代史》卷一百〇九，段落 jiu-wudaishi-205deb4a7860-p002627；EPUB电子本，纸本及异文待核", "id": "2a29c978-16f7-5be6-b10f-2306b9f7c59e"}, {"title": "宋史·卷253·孙行友传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd391620db0dcdfa704b6c166979a0422e9213ef/content/books/zizhi-tongjian/vol-285/year-0946/part-01/sources/library/songshi-253-sun-xingyou/source.txt", "note": "《宋史》卷253·孙行友传，段落 songshi-9c6e46fee832-p057425；已核上下文，底本原字保留，纸本及异文待核。", "id": "31ed85da-feb1-562f-979e-f49d8e40b652"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ba6eb38778a9dc93b1118241befc00658469f072/content/books/zizhi-tongjian/vol-288/year-0948/part-01/sources/library/jiuwudaishi-101-march-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002452；EPUB电子本，纸本及异文待核", "id": "8870e64b-8ecc-563e-a46e-9bfab08b9141"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "王益（后汉供奉官）", "aliases": ["王益（供奉官）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉供奉官。948年奉诏赴凤翔，将赵匡赞牙兵调往京师，到长安受安友规、乔守温迎接。《通鉴》《旧五代史》记赵思绾在这个过程中夺城，《新五代史》则记为随侯益东归时起事，两种记载保留。与其他年代同名王益分开，生卒年未载。", "biography": null, "status": "draft", "id": "d7ff3354-10ca-5fe5-ae6e-48cacc0763ad"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "时知化", "aliases": ["時知化"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉供奉官。《旧五代史》记948年与王益共同将赵匡赞部下三百余牙兵从凤翔部署赴京，这批牙兵后来在长安起事。生卒年未载。", "biography": null, "status": "draft", "id": "f7ccac04-5a3c-5cb2-b24f-7edaa31d3450"}, {"name": "赵思绾", "aliases": ["趙思綰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州人，原在赵在礼军中，后来成为赵匡赞牙将。948年王景崇试图令赵匡赞牙兵刺面防逃时，主动提出先刺自己以率众。齐藏珍建议将其杀死，王景崇不听。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b571162d-9596-5439-a443-f33cd87ea628"}, {"name": "常彦卿", "aliases": ["常彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵思绾党羽。948年部队被召赴京时，赵思绾向其表达忧惧，常彦卿建议临机应变，不要再说。生卒年未载。", "biography": null, "status": "draft", "id": "aae86d4a-7087-5ec9-95db-380c022a92b1"}, {"name": "安友规", "aliases": ["安友規"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "948年任永兴节度副使，与乔守温迎接王益，并允许赵思绾部下入城携家眷。赵思绾夺城后，安友规等逃离。《新五代史》把迎接对象写为侯益，异说保留。生卒年未载。", "biography": null, "status": "draft", "id": "d383a5c5-cfdc-534e-9b17-9211fc3ae2d2"}, {"name": "乔守温", "aliases": ["喬守溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "948年任永兴巡检，与安友规迎接奉诏调兵的王益；赵思绾部下获准入城后起事，乔守温等逃离。生卒年未载。", "biography": null, "status": "draft", "id": "b29f298b-bcd8-5fdf-a1e8-5be16281669e"}, {"name": "王守恩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王建立的儿子，与张从恩是姻亲。947年在上党，以左骁卫大将军身份被张从恩暂派为巡检使，协助赵行迁。姻亲具体双方未明，不补具体婚配，生卒年未载。", "biography": null, "status": "draft", "id": "72fe9a16-4716-54d0-bc82-5e7feadc013e"}, {"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "靖边庭", "aliases": ["靖邊庭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "虢州伶人。948年杀团练使田令方，驱掠州民投赵思绾，经过潼关时遭守军击败，部众溃散。《宋史》补称他因田令方与其妻有私情而愤怒，率数人夜入州署杀人，细节归于该书。生卒年未载。", "biography": null, "status": "draft", "id": "9a4c44ef-7271-5e70-9709-a6ad898ea784"}, {"name": "田令方", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 948, "description": "后汉虢州团练使，田钦祚的父亲。948年被伶人靖边庭杀害。《宋史》将此事与田令方和靖边庭妻的私情联系，史书动机叙述与死亡事实分开。出生年未载。", "biography": null, "status": "draft", "id": "6789690b-633f-5e41-b8e7-0d0e25e348d5"}, {"name": "田钦祚", "aliases": ["田欽祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《宋史》记田令方之子，田令方任后汉虢州团练使，被靖边庭杀害。传记随后记朝廷录田钦祚为殿直、改供奉官，但具体年月未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f14e439e-31ea-569e-b12d-b8c7096c504f"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "耶律忠", "aliases": ["邪律忠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，曾以义武节度副使身份代孙方简任定州节度使。《通鉴》将任命放在契丹皇帝北归时，《旧五代史》记在耶律阮继位后。948年与麻答等焚掠定州、驱走居民并北返，任命次序差异保留。生卒年未载。", "biography": null, "status": "draft", "id": "63b7b2f5-190c-59e4-8d60-a5c869179c51"}, {"name": "孙方简", "aliases": ["孫方簡", "孙方谏", "孫方諫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》称中山人，聚众于狼山，归附后晋后任东北招收指挥使，后来转投契丹并拘执刘延翰。《宋史》孙行友传写作孙方谏，记他是孙行友的兄子；《资治通鉴》记孙行友是其弟，亲属记载冲突待核。姓名字形与主体按狼山、职衔和事迹对应复用，生卒年未核。", "biography": null, "status": "draft", "id": "17e0109c-1d9d-5437-a7d0-5c7be7b6beb8"}, {"name": "刘在明", "aliases": ["劉在明"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘在明，原戍易州将领。", "biography": null, "status": "draft", "id": "cb5c0d5f-5cf3-50c5-9e63-1b219aa861b0"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "孙行友", "aliases": ["孫行友"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "与孙方简聚众于狼山，借孙深意的术及边民避乱扩展部众。《宋史》记为莫州清苑人，出身务农，后任孙方谏的副手；《资治通鉴》记为孙方简之弟，《宋史》却记孙方谏为他的兄子，亲属与籍贯表述分别保留待核。生卒年未核。", "biography": null, "status": "draft", "id": "297fda14-1470-5546-b76b-7b2461eb1d3d"}, {"name": "孙方遇", "aliases": ["孫方遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》记为孙方简奏请任泰州刺史者，与孙氏诸人共同抵御契丹。《宋史》在相应任职处写作行义，是否同人尚待核，没有直接合并。与孙方简、孙行友的具体长幼未据省略称谓确定，生卒年未载。", "biography": null, "status": "draft", "id": "70c064ed-cb05-53be-9844-abe7c2a4844d"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
